import{_ as d,o as e,c as o,aQ as r}from"./chunks/framework.DUI5EIbQ.js";const u=JSON.parse('{"title":"CSS单词库整合手册","description":"","frontmatter":{},"headers":[],"relativePath":"notes/css.md","filePath":"notes/css.md"}'),a={name:"notes/css.md"};function c(i,t,h,l,n,s){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="css单词库整合手册" tabindex="-1">CSS单词库整合手册 <a class="header-anchor" href="#css单词库整合手册" aria-label="Permalink to &quot;CSS单词库整合手册&quot;">​</a></h1><h2 id="一、css基础引入与嵌套" tabindex="-1">一、CSS基础引入与嵌套 <a class="header-anchor" href="#一、css基础引入与嵌套" aria-label="Permalink to &quot;一、CSS基础引入与嵌套&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能描述</th><th>语法/代码示例</th><th>说明</th></tr></thead><tbody><tr><td>CSS引入</td><td><code>&lt;link rel=&quot;stylesheet&quot; href=&quot;css文件路径&quot;&gt;</code></td><td>外部引入CSS文件的标准语法</td></tr><tr><td>中文转URI码</td><td><code>encodeURI(&#39;转码内容&#39;)</code></td><td>将中文等特殊字符转换为URI编码</td></tr><tr><td>URI码转中文</td><td><code>decodeURI(&#39;URI编码内容&#39;)</code></td><td>将URI编码还原为中文</td></tr><tr><td>嵌套网页</td><td><code>&lt;iframe src=&quot;目标页面路径&quot; width=&quot;100%&quot; height=&quot;310px&quot; frameborder=&quot;0&quot;&gt;&lt;/iframe&gt;</code></td><td>嵌入其他网页，frameborder=&quot;0&quot;隐藏边框</td></tr></tbody></table><h2 id="二、视口设置-移动端核心" tabindex="-1">二、视口设置（移动端核心） <a class="header-anchor" href="#二、视口设置-移动端核心" aria-label="Permalink to &quot;二、视口设置（移动端核心）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>语法示例</th><th>功能说明</th></tr></thead><tbody><tr><td>视口元标签</td><td><code>&lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=0&quot;&gt;</code></td><td>适配移动端显示</td></tr><tr><td>width=device-width</td><td>-</td><td>视口宽度等于设备屏幕宽度</td></tr><tr><td>initial-scale</td><td>initial-scale=1.0</td><td>页面初次显示的缩放比例</td></tr><tr><td>maximum-scale</td><td>maximum-scale=1.0</td><td>页面最大缩放比例</td></tr><tr><td>user-scalable</td><td>user-scalable=0</td><td>0为禁止用户缩放，1为允许</td></tr></tbody></table><h2 id="三、基础样式属性" tabindex="-1">三、基础样式属性 <a class="header-anchor" href="#三、基础样式属性" aria-label="Permalink to &quot;三、基础样式属性&quot;">​</a></h2><h3 id="_3-1-宽高与盒模型" tabindex="-1">3.1 宽高与盒模型 <a class="header-anchor" href="#_3-1-宽高与盒模型" aria-label="Permalink to &quot;3.1 宽高与盒模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>语法示例</th><th>功能说明</th></tr></thead><tbody><tr><td>宽度</td><td><code>width: 12px;</code> / <code>width: 100%;</code></td><td>设置元素宽度，支持固定值和百分比</td></tr><tr><td>高度</td><td><code>height: 12px;</code> / <code>height: auto;</code></td><td>设置元素高度，auto为自动适应内容</td></tr><tr><td>标准盒模型</td><td><code>box-sizing: content-box;</code></td><td>border和padding向外扩展（默认）</td></tr><tr><td>CSS3盒模型</td><td><code>box-sizing: border-box;</code></td><td>border和padding向内扩展，不改变元素总宽高</td></tr></tbody></table><h3 id="_3-2-字体属性" tabindex="-1">3.2 字体属性 <a class="header-anchor" href="#_3-2-字体属性" aria-label="Permalink to &quot;3.2 字体属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>语法示例</th><th>取值说明</th></tr></thead><tbody><tr><td>字体类型</td><td><code>font-family: &quot;宋体&quot;, &quot;Microsoft YaHei&quot;;</code></td><td>指定字体，多个字体用逗号分隔，优先级从左到右</td></tr><tr><td>字体大小</td><td><code>font-size: 12px;</code> / <code>font-size: calc(375px / 6.4);</code></td><td>支持固定值、calc计算</td></tr><tr><td>字体粗细</td><td><code>font-weight: 400;</code> / <code>font-weight: normal;</code> / <code>font-weight: bold;</code></td><td>100-900取值，400=normal，700=bold，无单位</td></tr><tr><td>字体样式</td><td><code>font-style: italic;</code> / <code>font-style: normal;</code></td><td>italic为斜体，normal为正常样式</td></tr><tr><td>复合属性</td><td><code>font: font-style font-weight font-size/line-height font-family;</code></td><td>示例：<code>font: italic 700 16px &#39;Microsoft YaHei&#39;;</code>，顺序不可乱</td></tr></tbody></table><h3 id="_3-3-文本属性" tabindex="-1">3.3 文本属性 <a class="header-anchor" href="#_3-3-文本属性" aria-label="Permalink to &quot;3.3 文本属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>语法示例</th><th>功能说明</th></tr></thead><tbody><tr><td>文本颜色</td><td><code>color: red;</code> / <code>color: #ff0000;</code> / <code>color: rgb(255,0,0);</code></td><td>支持英文单词、十六进制、RGB格式</td></tr><tr><td>文本对齐</td><td><code>text-align: center;</code> / <code>text-align: left;</code> / <code>text-align: right;</code></td><td>文本水平对齐方式</td></tr><tr><td>两端对齐</td><td><code>text-align: justify;</code> + <code>text-align-last: justify;</code></td><td>使文本铺满容器宽度（Edge浏览器适配）</td></tr><tr><td>文本装饰</td><td><code>text-decoration: none;</code> / <code>underline;</code> / <code>overline;</code> / <code>line-through;</code></td><td>none取消下划线（常用于a标签），underline下划线，overline上划线，line-through删除线</td></tr><tr><td>首行缩进</td><td><code>text-indent: 2em;</code></td><td>首行缩进2个字符宽度</td></tr><tr><td>行高</td><td><code>line-height: 26px;</code></td><td>设置行间距，可用于垂直居中</td></tr><tr><td>字符间距</td><td><code>letter-spacing: 2px;</code></td><td>单个字符之间的间距</td></tr><tr><td>单词间距</td><td><code>word-spacing: 25px;</code></td><td>英文单词之间的间距</td></tr></tbody></table><h3 id="_3-4-背景属性" tabindex="-1">3.4 背景属性 <a class="header-anchor" href="#_3-4-背景属性" aria-label="Permalink to &quot;3.4 背景属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>语法示例</th><th>取值说明</th></tr></thead><tbody><tr><td>背景颜色</td><td><code>background-color: red;</code> / <code>background: rgba(125,125,125,0.5);</code></td><td>rgba支持半透明，不影响内容</td></tr><tr><td>背景图片</td><td><code>background-image: url(图片路径);</code></td><td>引入背景图片</td></tr><tr><td>背景平铺</td><td><code>background-repeat: no-repeat;</code> / <code>repeat-x;</code> / <code>repeat-y;</code></td><td>no-repeat不平铺，repeat-x横向平铺，repeat-y纵向平铺</td></tr><tr><td>背景位置</td><td><code>background-position: top right;</code> / <code>100px 50px;</code></td><td>支持方位名词、固定单位，先水平后垂直</td></tr><tr><td>背景固定</td><td><code>background-attachment: fixed;</code> / <code>scroll;</code></td><td>fixed背景不随滚动条移动，scroll跟随移动</td></tr><tr><td>背景大小</td><td><code>background-size: cover;</code> / <code>contain;</code> / <code>1000px 500px;</code></td><td>cover完全覆盖盒子，contain完全包含在盒子内</td></tr><tr><td>背景复合写法</td><td><code>background: red url(&quot;图片路径&quot;) no-repeat fixed 20px 20px;</code></td><td>顺序：颜色 图片 平铺 固定 位置</td></tr><tr><td>渐变色背景</td><td><code>background-image: linear-gradient(to right, red 50%, yellow 70%, blue);</code></td><td>线性渐变，支持多颜色节点</td></tr></tbody></table><h3 id="_3-5-边框属性" tabindex="-1">3.5 边框属性 <a class="header-anchor" href="#_3-5-边框属性" aria-label="Permalink to &quot;3.5 边框属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>语法示例</th><th>取值说明</th></tr></thead><tbody><tr><td>边框复合写法</td><td><code>border: 10px solid yellowgreen;</code></td><td>顺序：宽度 样式 颜色</td></tr><tr><td>单边边框</td><td><code>border-right: 20px dashed red;</code></td><td>支持left/top/right/bottom，样式：solid实线、dashed虚线、dotted点线</td></tr><tr><td>边框合并</td><td><code>border-collapse: collapse;</code></td><td>用于表格，合并相邻边框</td></tr><tr><td>边框圆角</td><td><code>border-radius: 10px;</code> / <code>border-radius: 50%;</code></td><td>数值为圆角半径，50%可实现圆形（需宽高相等）</td></tr><tr><td>边框图片</td><td><code>border-image: url(&quot;边框图片路径&quot;) 167/20px round;</code></td><td>组合写法：路径 截取距离/边框宽度 排布方式</td></tr><tr><td>边框图片截取</td><td><code>border-image-slice: 167 167 167 167;</code></td><td>顺时针方向截取边框图片四个角</td></tr><tr><td>边框图片排布</td><td><code>border-image-repeat: repeat;</code> / <code>round;</code> / <code>stretch;</code></td><td>repeat平铺，round环绕，stretch拉伸</td></tr></tbody></table><h3 id="_3-6-内边距与外边距" tabindex="-1">3.6 内边距与外边距 <a class="header-anchor" href="#_3-6-内边距与外边距" aria-label="Permalink to &quot;3.6 内边距与外边距&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>语法示例</th><th>功能说明</th></tr></thead><tbody><tr><td>内边距（padding）</td><td>复合写法：<code>padding: 20px;</code> / <code>20px 50px;</code> / <code>20px 50px 80px 100px;</code></td><td>分别对应：四边相同、上下/左右、上/右/下/左</td></tr><tr><td>单边内边距</td><td><code>padding-left: 20px;</code></td><td>支持top/right/bottom/left</td></tr><tr><td>外边距（margin）</td><td>复合写法：<code>margin: 50px 100px;</code></td><td>写法同padding</td></tr><tr><td>单边外边距</td><td><code>margin-top: 20px;</code></td><td>支持top/right/bottom/left</td></tr><tr><td>块元素居中</td><td><code>margin: 0 auto;</code></td><td>水平居中，需设置宽度</td></tr><tr><td>溢出处理</td><td><code>overflow: hidden;</code> / <code>visible;</code> / <code>scroll;</code> / <code>auto;</code></td><td>hidden溢出隐藏，scroll强制显示滚动条，auto自动判断</td></tr></tbody></table><h2 id="四、选择器" tabindex="-1">四、选择器 <a class="header-anchor" href="#四、选择器" aria-label="Permalink to &quot;四、选择器&quot;">​</a></h2><h3 id="_4-1-基础选择器与伪类" tabindex="-1">4.1 基础选择器与伪类 <a class="header-anchor" href="#_4-1-基础选择器与伪类" aria-label="Permalink to &quot;4.1 基础选择器与伪类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选择器类型</th><th>语法示例</th><th>功能说明</th></tr></thead><tbody><tr><td>链接伪类（LVHA顺序）</td><td><code>a:link{}</code> / <code>a:visited{}</code> / <code>a:hover{}</code> / <code>a:active{}</code></td><td>link未访问，visited已访问，hover鼠标经过，active鼠标按下</td></tr><tr><td>input聚焦伪类</td><td><code>input:focus{}</code></td><td>选择获取光标的input元素</td></tr><tr><td>结构伪类</td><td><code>:first-child</code> / <code>:last-child</code> / <code>:nth-child(even)</code> / <code>:nth-child(odd)</code></td><td>分别对应：第一个子元素、最后一个子元素、偶数子元素、奇数子元素</td></tr><tr><td>排除伪类</td><td><code>:not(:last-child)</code></td><td>选择除最后一个子元素外的所有元素</td></tr><tr><td>类型伪类</td><td><code>:first-of-type</code> / <code>:last-of-type</code> / <code>:nth-of-type(n)</code></td><td>按元素类型选择对应位置的元素</td></tr><tr><td>选中伪类</td><td><code>:checked</code></td><td>匹配选中的单选框、复选框等元素</td></tr></tbody></table><h3 id="_4-2-伪元素" tabindex="-1">4.2 伪元素 <a class="header-anchor" href="#_4-2-伪元素" aria-label="Permalink to &quot;4.2 伪元素&quot;">​</a></h3><table tabindex="0"><thead><tr><th>伪元素</th><th>语法示例</th><th>功能说明</th></tr></thead><tbody><tr><td>内容前插入</td><td><code>div::before{ content: &quot;&quot;; display: block; }</code></td><td>在元素内容前创建虚拟元素，默认行内元素</td></tr><tr><td>内容后插入</td><td><code>div::after{ content: &quot;&quot;; display: block; }</code></td><td>在元素内容后创建虚拟元素，默认行内元素</td></tr></tbody></table><h2 id="五、布局相关" tabindex="-1">五、布局相关 <a class="header-anchor" href="#五、布局相关" aria-label="Permalink to &quot;五、布局相关&quot;">​</a></h2><h3 id="_5-1-显示模式" tabindex="-1">5.1 显示模式 <a class="header-anchor" href="#_5-1-显示模式" aria-label="Permalink to &quot;5.1 显示模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>显示属性</th><th>语法示例</th><th>功能说明</th></tr></thead><tbody><tr><td>块元素</td><td><code>display: block;</code></td><td>独占一行，可设置宽高，行内元素转块元素</td></tr><tr><td>行内元素</td><td><code>display: inline;</code></td><td>不独占一行，不可设置宽高，块元素转行内元素</td></tr><tr><td>行内块元素</td><td><code>display: inline-block;</code></td><td>不独占一行，可设置宽高</td></tr><tr><td>消除行内块缝隙</td><td><code>父元素font-size: 0;</code></td><td>解决inline-block元素之间的默认间距</td></tr><tr><td>隐藏元素（不占位）</td><td><code>display: none;</code></td><td>元素隐藏且不占据页面空间</td></tr><tr><td>隐藏元素（占位）</td><td><code>visibility: hidden;</code></td><td>元素隐藏但保留占位空间</td></tr><tr><td>显示元素</td><td><code>visibility: visible;</code></td><td>元素正常显示</td></tr></tbody></table><h3 id="_5-2-浮动布局" tabindex="-1">5.2 浮动布局 <a class="header-anchor" href="#_5-2-浮动布局" aria-label="Permalink to &quot;5.2 浮动布局&quot;">​</a></h3><table tabindex="0"><thead><tr><th>浮动属性</th><th>语法示例</th><th>功能说明</th></tr></thead><tbody><tr><td>左浮动</td><td><code>float: left;</code></td><td>元素向左浮动</td></tr><tr><td>右浮动</td><td><code>float: right;</code></td><td>元素向右浮动</td></tr><tr><td>中间浮动</td><td><code>float: content;</code></td><td>元素向中间浮动</td></tr><tr><td>清除浮动-额外标签法</td><td><code>&lt;div style=&quot;clear: both;&quot;&gt;&lt;/div&gt;</code></td><td>在最后一个浮动元素后添加块级元素</td></tr><tr><td>清除浮动-overflow法</td><td><code>父元素{ overflow: hidden; }</code></td><td>给浮动元素的父容器添加</td></tr><tr><td>清除浮动-伪元素法</td><td><code>.clearfix::after{ content: &quot;&quot;; display: block; clear: both; height: 0; visibility: hidden; }</code> + <code>.clearfix{ *zoom: 1; }</code></td><td>兼容各浏览器，不添加额外标签</td></tr><tr><td>清除浮动-双伪元素法</td><td><code>.clearfix::before,.clearfix::after{ content: &quot;&quot;; display: table; }</code> + <code>.clearfix::after{ clear: both; }</code> + <code>.clearfix{ *zoom: 1; }</code></td><td>更完善的清除浮动方案</td></tr></tbody></table><h3 id="_5-3-弹性布局-flex" tabindex="-1">5.3 弹性布局（Flex） <a class="header-anchor" href="#_5-3-弹性布局-flex" aria-label="Permalink to &quot;5.3 弹性布局（Flex）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>语法示例</th><th>取值说明</th><th>适用对象</th></tr></thead><tbody><tr><td>开启弹性布局</td><td><code>display: flex;</code></td><td>-</td><td>父元素</td></tr><tr><td>主轴排列</td><td><code>justify-content: flex-start;</code></td><td>flex-start（左到右）、center（居中）、flex-end（右到左）、space-between（等距分隔）、space-around（等距环绕）、space-evenly（平均分）</td><td>父元素</td></tr><tr><td>次轴排列（单行）</td><td><code>align-items: flex-start;</code></td><td>flex-start（靠上）、center（居中）、flex-end（靠下）、baseline（文字基线对齐）、stretch（拉伸填满）</td><td>父元素</td></tr><tr><td>换行设置</td><td><code>flex-wrap: wrap;</code></td><td>nowrap（不换行）、wrap（向下换行）、wrap-reverse（向上换行）</td><td>父元素</td></tr><tr><td>次轴排列（多行）</td><td><code>align-content: flex-start;</code></td><td>取值同justify-content</td><td>父元素</td></tr><tr><td>主轴方向</td><td><code>flex-direction: row;</code></td><td>row（水平左到右）、row-reverse（水平右到左）、column（垂直上到下）、column-reverse（垂直下到上）</td><td>父元素</td></tr><tr><td>子元素占比</td><td><code>flex: 1;</code></td><td>数值表示子元素对剩余空间的占比</td><td>子元素</td></tr><tr><td>子元素排序</td><td><code>order: -1;</code></td><td>默认0，值越小越靠前</td><td>子元素</td></tr><tr><td>单个子元素次轴排列</td><td><code>align-self: flex-start;</code></td><td>取值同align-items，单独控制某个子元素</td><td>子元素</td></tr></tbody></table><h3 id="_5-4-网格布局-grid" tabindex="-1">5.4 网格布局（Grid） <a class="header-anchor" href="#_5-4-网格布局-grid" aria-label="Permalink to &quot;5.4 网格布局（Grid）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>语法示例</th><th>功能说明</th></tr></thead><tbody><tr><td>开启网格布局</td><td><code>display: grid;</code></td><td>父元素设置</td></tr><tr><td>划分网格（行）</td><td><code>grid-template-rows: 100px 100px 200px;</code></td><td>定义每行高度，多个值用空格分隔</td></tr><tr><td>划分网格（列）</td><td><code>grid-template-columns: 200px 300px;</code> / <code>grid-template-columns: repeat(5, 20%);</code></td><td>repeat(5,20%)表示5列，每列20%</td></tr><tr><td>网格复合写法</td><td><code>grid-template: 100px 100px 200px / 200px 300px;</code></td><td>顺序：行 列</td></tr><tr><td>行间距</td><td><code>grid-row-gap: 5px;</code></td><td>网格行与行之间的间距</td></tr><tr><td>列间距</td><td><code>grid-column-gap: 5px;</code></td><td>网格列与列之间的间距</td></tr></tbody></table><h2 id="六、特殊效果" tabindex="-1">六、特殊效果 <a class="header-anchor" href="#六、特殊效果" aria-label="Permalink to &quot;六、特殊效果&quot;">​</a></h2><h3 id="_6-1-阴影效果" tabindex="-1">6.1 阴影效果 <a class="header-anchor" href="#_6-1-阴影效果" aria-label="Permalink to &quot;6.1 阴影效果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阴影类型</th><th>语法示例</th><th>取值说明</th></tr></thead><tbody><tr><td>盒子阴影</td><td><code>box-shadow: h-shadow v-shadow blur spread color inset;</code></td><td>h-shadow（水平阴影，必需）、v-shadow（垂直阴影，必需）、blur（模糊距离）、spread（阴影尺寸）、color（阴影颜色）、inset（内部阴影）</td></tr><tr><td>文字阴影</td><td><code>text-shadow: h-shadow v-shadow blur color;</code></td><td>取值同box-shadow，无spread和inset</td></tr></tbody></table><h3 id="_6-2-鼠标样式" tabindex="-1">6.2 鼠标样式 <a class="header-anchor" href="#_6-2-鼠标样式" aria-label="Permalink to &quot;6.2 鼠标样式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>语法示例</th><th>效果说明</th></tr></thead><tbody><tr><td><code>cursor: default;</code></td><td>默认鼠标样式（箭头）</td></tr><tr><td><code>cursor: text;</code></td><td>文本选择样式（I型）</td></tr><tr><td><code>cursor: pointer;</code></td><td>小手样式（常用于可点击元素）</td></tr><tr><td><code>cursor: move;</code></td><td>移动样式（十字箭头）</td></tr><tr><td><code>cursor: not-allowed;</code></td><td>禁止样式</td></tr><tr><td><code>cursor: zoom-in;</code></td><td>放大样式</td></tr><tr><td><code>cursor: none!important;</code></td><td>隐藏鼠标</td></tr></tbody></table><h3 id="_6-3-文本溢出处理" tabindex="-1">6.3 文本溢出处理 <a class="header-anchor" href="#_6-3-文本溢出处理" aria-label="Permalink to &quot;6.3 文本溢出处理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>效果</th><th>语法组合</th><th>说明</th></tr></thead><tbody><tr><td>单行文本溢出省略</td><td><code>white-space: nowrap; overflow: hidden; text-overflow: ellipsis;</code></td><td>必须同时设置三个属性</td></tr><tr><td>多行文本溢出省略</td><td><code>overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;</code></td><td>-webkit-line-clamp控制显示行数，需配合高度调整</td></tr><tr><td>自动换行</td><td><code>word-wrap: break-word;</code></td><td>英文单词自动换行</td></tr><tr><td>强制换行</td><td><code>word-break: break-all;</code></td><td>强制英文单词拆分换行</td></tr></tbody></table><h3 id="_6-4-三角形制作" tabindex="-1">6.4 三角形制作 <a class="header-anchor" href="#_6-4-三角形制作" aria-label="Permalink to &quot;6.4 三角形制作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>三角形类型</th><th>语法示例</th><th>说明</th></tr></thead><tbody><tr><td>正三角形</td><td><code>width: 0; height: 0; border: 50px solid transparent; border-bottom: 50px solid yellow;</code></td><td>宽高为0，三边透明，一边有颜色</td></tr><tr><td>直角三角形</td><td><code>width: 0; height: 0; border-top: 100px solid transparent; border-right: 50px solid skyblue;</code></td><td>按需设置相邻两边透明，另外一边有颜色</td></tr></tbody></table><h3 id="_6-5-图片相关处理" tabindex="-1">6.5 图片相关处理 <a class="header-anchor" href="#_6-5-图片相关处理" aria-label="Permalink to &quot;6.5 图片相关处理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>语法示例</th><th>说明</th></tr></thead><tbody><tr><td>响应式图片</td><td><code>&lt;img src=&quot;默认图&quot; srcset=&quot;url 2x, url 3x&quot; alt=&quot;&quot;&gt;</code></td><td>根据屏幕分辨率加载不同图片</td></tr><tr><td>图片适配</td><td><code>object-fit: contain;</code></td><td>保持图片原有尺寸比例适配容器</td></tr><tr><td>消除img底部缝隙</td><td><code>vertical-align: bottom;</code> / <code>display: block;</code></td><td>解决图片与文字对齐时的默认缝隙</td></tr></tbody></table><h2 id="七、定位相关" tabindex="-1">七、定位相关 <a class="header-anchor" href="#七、定位相关" aria-label="Permalink to &quot;七、定位相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>定位方式</th><th>语法示例</th><th>定位基准</th><th>特点</th></tr></thead><tbody><tr><td>相对定位</td><td><code>position: relative;</code></td><td>自身原有位置</td><td>不脱离文档流，可通过top/right/bottom/left偏移</td></tr><tr><td>绝对定位</td><td><code>position: absolute;</code></td><td>最近一级有定位的祖先元素</td><td>脱离文档流，需配合相对定位使用</td></tr><tr><td>固定定位</td><td><code>position: fixed;</code></td><td>浏览器窗口</td><td>脱离文档流，固定在窗口某个位置，不随滚动条移动</td></tr><tr><td>定位居中</td><td><code>position: absolute; left: 50%; top: 50%; margin-left: -150px; margin-top: -150px; width: 300px; height: 300px;</code></td><td>先移动父元素50%，再回移自身一半宽度/高度</td><td></td></tr></tbody></table><h2 id="八、过渡与变换" tabindex="-1">八、过渡与变换 <a class="header-anchor" href="#八、过渡与变换" aria-label="Permalink to &quot;八、过渡与变换&quot;">​</a></h2><h3 id="_8-1-过渡-transition" tabindex="-1">8.1 过渡（transition） <a class="header-anchor" href="#_8-1-过渡-transition" aria-label="Permalink to &quot;8.1 过渡（transition）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>语法示例</th><th>取值说明</th></tr></thead><tbody><tr><td>过渡复合写法</td><td><code>transition: all 1.5s 3s ease;</code></td><td>顺序：过渡属性 持续时间 延迟时间 速度曲线</td></tr><tr><td>过渡属性</td><td><code>transition-property: all;</code></td><td>指定需要过渡的样式，all表示所有样式</td></tr><tr><td>持续时间</td><td><code>transition-duration: 1.5s;</code></td><td>过渡效果的时间，单位秒（s）</td></tr><tr><td>延迟时间</td><td><code>transition-delay: 3s;</code></td><td>延迟多久开始过渡，单位秒（s）</td></tr><tr><td>速度曲线</td><td><code>transition-timing-function: ease;</code> / <code>linear;</code></td><td>ease默认（慢-快-慢），linear匀速</td></tr></tbody></table><h3 id="_8-2-2d变换-transform" tabindex="-1">8.2 2D变换（transform） <a class="header-anchor" href="#_8-2-2d变换-transform" aria-label="Permalink to &quot;8.2 2D变换（transform）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变换类型</th><th>语法示例</th><th>取值说明</th></tr></thead><tbody><tr><td>偏移</td><td><code>transform: translate(x, y);</code></td><td>x水平偏移，y垂直偏移，支持负值</td></tr><tr><td>旋转</td><td><code>transform: rotate(360deg);</code></td><td>单位deg，正数顺时针，负数逆时针</td></tr><tr><td>缩放</td><td><code>transform: scale(h, v);</code></td><td>h水平缩放，v垂直缩放，0-1缩小，大于1放大</td></tr><tr><td>倾斜</td><td><code>transform: skew(h, v);</code></td><td>h水平倾斜角度，v垂直倾斜角度，单位deg</td></tr><tr><td>组合变换</td><td><code>transform: translate(100px, 0) rotate(360deg);</code></td><td>可组合多个变换，注意顺序</td></tr><tr><td>变换基准点</td><td><code>transform-origin: top left;</code> / <code>100% 0;</code></td><td>默认为元素中心，可指定方位或坐标</td></tr></tbody></table><h3 id="_8-3-3d变换" tabindex="-1">8.3 3D变换 <a class="header-anchor" href="#_8-3-3d变换" aria-label="Permalink to &quot;8.3 3D变换&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变换类型</th><th>语法示例</th><th>说明</th></tr></thead><tbody><tr><td>视距设置</td><td><code>perspective: 800px;</code></td><td>父元素设置，实现近大远小的3D效果</td></tr><tr><td>Z轴偏移</td><td><code>transform: translateZ();</code></td><td>沿Z轴移动，正值靠近观察者</td></tr><tr><td>X轴旋转</td><td><code>transform: rotateX();</code></td><td>沿X轴旋转，类似翻本效果</td></tr><tr><td>Y轴旋转</td><td><code>transform: rotateY();</code></td><td>沿Y轴旋转，类似翻书效果</td></tr><tr><td>Z轴旋转</td><td><code>transform: rotateZ();</code></td><td>沿Z轴旋转，同2D的rotate()</td></tr></tbody></table><h2 id="九、帧动画-animation" tabindex="-1">九、帧动画（animation） <a class="header-anchor" href="#九、帧动画-animation" aria-label="Permalink to &quot;九、帧动画（animation）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>动画相关</th><th>语法示例</th><th>说明</th></tr></thead><tbody><tr><td>定义帧动画</td><td><code>@keyframes move { from{ left: 0px; } to { left: 200px; } }</code></td><td>from为起始状态，to为结束状态</td></tr><tr><td>百分比动画</td><td><code>@keyframes move { 0% {transform:translate(0);} 20% {transform:translate(200px,0);} 100% {transform:translate(0,400px);} }</code></td><td>支持多关键帧，0%为起始，100%为结束</td></tr><tr><td>应用动画</td><td><code>animation: move 1s linear 3s infinite alternate forwards;</code></td><td>顺序：动画名 持续时间 速度曲线 延迟时间 重复次数 方向 停止状态</td></tr><tr><td>动画暂停/运行</td><td><code>animation-play-state: paused;</code> / <code>running;</code></td><td>paused暂停，running运行</td></tr><tr><td>动画分割</td><td><code>animation: a 5s steps(5, end) infinite;</code></td><td>steps(n,start/end)，n为分割段数，start第一段不参与，end最后一段不参与</td></tr><tr><td>重复次数</td><td><code>animation-iteration-count: infinite;</code></td><td>infinite无限次，可指定具体次数</td></tr><tr><td>动画方向</td><td><code>animation-direction: alternate;</code> / <code>reverse;</code></td><td>alternate往复执行，reverse反向执行</td></tr><tr><td>停止状态</td><td><code>animation-fill-mode: forwards;</code> / <code>backwards;</code></td><td>forwards停在结束位置，backwards停在起始位置</td></tr></tbody></table><h2 id="十、媒体查询-响应式核心" tabindex="-1">十、媒体查询（响应式核心） <a class="header-anchor" href="#十、媒体查询-响应式核心" aria-label="Permalink to &quot;十、媒体查询（响应式核心）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语法格式</th><th>示例代码</th><th>说明</th></tr></thead><tbody><tr><td>基础语法</td><td><code>@media screen and (max-width: 1200px) { .box {} }</code></td><td>screen可省略，and两侧必须有空格</td></tr><tr><td>区间查询</td><td><code>@media screen and (max-width: 1200px) and (min-width: 992px) {}</code></td><td>闭合区间，匹配992px-1200px的屏幕</td></tr><tr><td>常见断点</td><td>-</td><td>大屏PC（&gt;1200px）、小屏PC（&gt;992px）、平板（&gt;760px）、手机（&lt;768px）</td></tr></tbody></table><h2 id="十一、less预处理语法" tabindex="-1">十一、Less预处理语法 <a class="header-anchor" href="#十一、less预处理语法" aria-label="Permalink to &quot;十一、Less预处理语法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>语法示例</th><th>说明</th></tr></thead><tbody><tr><td>导入Less文件</td><td><code>@import &quot;02-base.less&quot;;</code></td><td>@import与文件名之间有空格，结尾加分号，可省略扩展名</td></tr><tr><td>定义变量</td><td><code>@w: 100px;</code></td><td>变量名前加@，可存储尺寸、颜色等</td></tr><tr><td>使用变量</td><td><code>width: @w;</code></td><td>直接引用变量名</td></tr><tr><td>运算语法</td><td><code>width: @w - 50;</code> / <code>font-size: (30px / 2);</code></td><td>+-*两侧需有空格，除法需加括号</td></tr><tr><td>混入语法</td><td>定义：<code>.common { padding: 10px; }</code> 使用：<code>.box { .common; }</code></td><td>提取公共样式，直接引用类名</td></tr></tbody></table><h2 id="十二、表单相关css" tabindex="-1">十二、表单相关CSS <a class="header-anchor" href="#十二、表单相关css" aria-label="Permalink to &quot;十二、表单相关CSS&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>语法示例</th><th>说明</th></tr></thead><tbody><tr><td>取消input聚焦边框</td><td><code>input { outline: none; }</code></td><td>清除默认聚焦时的边框样式</td></tr><tr><td>禁止文本域拖拽</td><td><code>resize: none;</code></td><td>用于textarea，禁止调整大小</td></tr><tr><td>表单元素选中</td><td><code>input:checked{}</code></td><td>匹配选中的单选框、复选框</td></tr></tbody></table><h2 id="十三、特殊字符与文本格式" tabindex="-1">十三、特殊字符与文本格式 <a class="header-anchor" href="#十三、特殊字符与文本格式" aria-label="Permalink to &quot;十三、特殊字符与文本格式&quot;">​</a></h2><h3 id="_13-1-特殊字符" tabindex="-1">13.1 特殊字符 <a class="header-anchor" href="#_13-1-特殊字符" aria-label="Permalink to &quot;13.1 特殊字符&quot;">​</a></h3><table tabindex="0"><thead><tr><th>显示效果</th><th>语法</th><th>说明</th></tr></thead><tbody><tr><td>&gt;</td><td><code>&amp;gt;</code></td><td>大于号</td></tr><tr><td>&lt;</td><td><code>&amp;lt;</code></td><td>小于号</td></tr><tr><td>空格</td><td><code>&amp;nbsp;</code></td><td>不换行空格</td></tr><tr><td>&amp;</td><td><code>&amp;amp;</code></td><td>和号</td></tr><tr><td>&quot;</td><td><code>&amp;quot;</code></td><td>双引号</td></tr><tr><td>®</td><td><code>&amp;reg;</code></td><td>已注册标识</td></tr><tr><td>©</td><td><code>&amp;copy;</code></td><td>版权标识</td></tr><tr><td>™</td><td><code>&amp;trade;</code></td><td>商标标识</td></tr><tr><td>¥</td><td><code>&amp;yen;</code></td><td>人民币符号</td></tr></tbody></table><h3 id="_13-2-文本格式标签" tabindex="-1">13.2 文本格式标签 <a class="header-anchor" href="#_13-2-文本格式标签" aria-label="Permalink to &quot;13.2 文本格式标签&quot;">​</a></h3><table tabindex="0"><thead><tr><th>效果</th><th>标签示例</th><th>说明</th></tr></thead><tbody><tr><td>加粗</td><td><code>&lt;strong&gt;文本&lt;/strong&gt;</code> / <code>&lt;b&gt;文本&lt;/b&gt;</code></td><td>两者均为加粗效果</td></tr><tr><td>倾斜</td><td><code>&lt;em&gt;文本&lt;/em&gt;</code> / <code>&lt;i&gt;文本&lt;/i&gt;</code></td><td>两者均为倾斜效果</td></tr><tr><td>删除线</td><td><code>&lt;del&gt;文本&lt;/del&gt;</code> / <code>&lt;s&gt;文本&lt;/s&gt;</code></td><td>两者均为删除线效果</td></tr><tr><td>下划线</td><td><code>&lt;ins&gt;文本&lt;/ins&gt;</code> / <code>&lt;u&gt;文本&lt;/u&gt;</code></td><td>两者均为下划线效果</td></tr></tbody></table><h2 id="十四、权重规则" tabindex="-1">十四、权重规则 <a class="header-anchor" href="#十四、权重规则" aria-label="Permalink to &quot;十四、权重规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选择器/语法</th><th>权重优先级</th><th>说明</th></tr></thead><tbody><tr><td><code>!important</code></td><td>最高</td><td>例：<code>color: red !important;</code>，优先执行</td></tr><tr><td>行内样式</td><td>高</td><td>元素style属性中的样式</td></tr><tr><td>ID选择器</td><td>中高</td><td><code>#id{}</code></td></tr><tr><td>类选择器</td><td>中</td><td><code>.class{}</code></td></tr><tr><td>标签选择器</td><td>中低</td><td><code>div{}</code></td></tr><tr><td>通配符</td><td>低</td><td><code>*{}</code></td></tr><tr><td>继承样式</td><td>最低</td><td>从父元素继承的样式</td></tr></tbody></table>',67)])])}const x=d(a,[["render",c]]);export{u as __pageData,x as default};
